configfiles.configfile:
set -eu
mode="\$1"; input="\$2"; species="\$3"; renames="\$4"; sizes="\$5"; ref="\$6"; output="\$7"
\#\# roast takes a species up to the first '.', needs a leading letter, and deletes every line holding
\#\# 'maf' or 'eof' (speciesTree.c), so a name with either would lose its rows at exit 0.
case "\$ref" in
    ''|[!A-Za-z]*|*[!A-Za-z0-9_]*|*maf*|*eof*)
        echo "reference name must be a letter then letters, digits or _, without maf or eof: \$ref" >&2; exit 1;;
esac
\#\# GNU awk, never BusyBox awk: BusyBox truncates on a failed write and exits 0. gawk exits non-zero on a
\#\# failed write, and close() is checked as well, so a full disk fails the job.
case "\$mode" in
forward)
\#\# Every block of an axtToMaf pair is row 1 = the reference, row 2 = the query, with bare sequence names.
\#\# The rows are told apart by POSITION: names cannot be trusted (a query genome can have a sequence
\#\# with the reference's mitochondrion's name and length). Only the name token is replaced; every other
\#\# byte of the line, padding included, is kept.
gawk -v ref="\$ref" -v out="\$output" -v spfile="\$species" -v rnfile="\$renames" -v szfile="\$sizes" '
function die(m) { print "maf_name_rows: " m > "/dev/stderr"; failed = 1; exit 1 }
function endblock() {
    if (rows != 2) die("the block at line " bline " has " rows " s line(s), not 2 (the reference, then the query)")
    inblock = 0
}
function put(name,   lead) {
    match(\$0, /^s +/); lead = substr(\$0, 1, RLENGTH)
    print lead name substr(\$0, RLENGTH + 1 + length(f[2])) > out
}
BEGIN {
    n = 0
    while ((r = (getline line < spfile)) > 0) {
        sub(/\r\$/, "", line)
        if (line ~ /^[ \t]*\$/) continue
        n++
        if (n > 1 || split(line, p, "\t") != 2) die("the species dataset must be ONE line, label TAB species name: " line)
        label = p[1]; sp = p[2]
    }
    if (r < 0) die("cannot read the species dataset")
    if (n == 0) die("the species dataset is empty")
    if (label !~ /^[^ ]+\$/) die("the label must be one word: " label)
    if (sp !~ /^[A-Za-z][A-Za-z0-9_]*\$/ || sp ~ /maf|eof/) die("species name " sp " cannot go through roast: a letter then letters, digits or _, without maf or eof")
    if (sp == ref) die("species name " sp " is the reference name")
    ln = 0
    while ((r = (getline line < rnfile)) > 0) {
        ln++
        sub(/\r\$/, "", line)
        if (ln == 1) {
            if (line != "genome\thub_name\toriginal_name") die("the renames table must start with the header genome, hub_name, original_name: " line)
            continue
        }
        if (line ~ /^[ \t]*\$/) continue
        if (split(line, p, "\t") != 3) die("renames line " ln " does not have 3 columns: " line)
        if (p[1] != label) continue
        if ((p[3] in hub) && hub[p[3]] != p[2]) die("renames give " p[3] " two hub names for " label)
        hub[p[3]] = p[2]; nren++
    }
    if (r < 0) die("cannot read the renames table")
    if (ln == 0) die("the renames table is empty (it needs at least its header)")
    ns = 0
    while ((r = (getline line < szfile)) > 0) {
        if (line ~ /^[ \t]*\$/) continue
        if (split(line, p, "\t") < 2 || p[2] !~ /^[0-9]+\$/) die("sizes line is not sequence TAB size: " line)
        size[p[1]] = p[2]; ns++
    }
    if (r < 0) die("cannot read the reference sizes")
    if (ns == 0) die("the reference sizes are empty")
}
{
    if (\$0 ~ /^[ \t]*\$/) { if (inblock) endblock(); print > out; next }
    c = substr(\$0, 1, 1)
    if (c == "a" && (\$0 == "a" || substr(\$0, 2, 1) == " ")) {
        if (inblock) endblock()
        inblock = 1; rows = 0; bline = NR; blocks++
        print > out; next
    }
    if (!inblock) {
        if (c == "#") { print > out; next }
        die("line " NR " is outside a block and is not a header line: " substr(\$0, 1, 60))
    }
    if (c != "s" || substr(\$0, 2, 1) != " ") die("line " NR " in a block is not an s line, and a pairwise MAF has only s lines: " substr(\$0, 1, 60))
    rows++
    if (rows > 2) die("the block at line " bline " has more than 2 s lines (the reference, then the query)")
    if (split(\$0, f, " ") != 7) die("the s line at line " NR " does not have 7 fields")
    if (rows == 1) {
        q = f[2]
        if (!(q in size)) die("reference sequence " q " (row 1, line " NR ") is not in the reference sizes: rows must carry bare sequence names")
        if (f[6] != size[q]) die("reference sequence " q " has size " f[6] " at line " NR ", but " size[q] " in the reference sizes")
        if (f[5] != "+") die("the reference row at line " NR " is on the - strand")
        \#\# multiz merges unsorted input wrongly with exit status 0, so the order is checked here
        if (q != cur) {
            if (q in done) die("reference sequence " q " starts again at line " NR " after another sequence began: the input is not sorted")
            if (cur != "") done[cur] = 1
            cur = q; last = -1; nseq++
        }
        if (f[3] + 0 < last) die("the reference start goes backwards at line " NR ": " q " " f[3] " after " last)
        last = f[3] + 0
        put(ref "." q)
    } else {
        if (f[2] in hub) { put(sp "." hub[f[2]]); renamed++ } else put(sp "." f[2])
    }
}
END {
    if (failed) exit 1
    if (inblock) endblock()
    printf "" > out
    if (close(out) != 0) die("cannot write " out)
    print "blocks: " blocks + 0 " on " nseq + 0 " reference sequence(s)"
    print "species: " sp " (label " label ", " nren + 0 " sequence rename(s) for it)"
    print "query rows renamed: " renamed + 0
}' "\$input"
;;
species)
\#\# After roast: every s, i, e and q line has species.sequence; only the species part is renamed, the
\#\# reference's rows never, and every other line is copied unchanged.
gawk -v ref="\$ref" -v out="\$output" -v rnfile="\$renames" '
function die(m) { print "maf_name_rows: " m > "/dev/stderr"; failed = 1; exit 1 }
BEGIN {
    ln = 0; nmap = 0
    while ((r = (getline line < rnfile)) > 0) {
        ln++
        sub(/\r\$/, "", line)
        if (ln == 1) {
            if (line != "from\tto") die("the species renames must start with the header from, to: " line)
            continue
        }
        if (line ~ /^[ \t]*\$/) continue
        if (split(line, p, "\t") != 2 || p[1] !~ /^[^ .]+\$/ || p[2] !~ /^[^ .]+\$/) die("species renames line " ln " is not from TAB to, each without a . or a space: " line)
        if (p[1] == ref || p[2] == ref) die("species renames line " ln " names the reference " ref)
        if (p[1] in map) die("species " p[1] " is renamed twice")
        if (p[2] in target) die("two species are renamed to " p[2])
        map[p[1]] = p[2]; target[p[2]] = 1; nmap++
    }
    if (r < 0) die("cannot read the species renames")
    if (nmap == 0) die("the species renames table has no rows")
}
{
    c = substr(\$0, 1, 1)
    if ((c == "s" || c == "i" || c == "e" || c == "q") && substr(\$0, 2, 1) == " ") {
        split(\$0, f, " ")
        d = index(f[2], ".")
        if (d < 2) die("the row at line " NR " has no species prefix: " f[2])
        s = substr(f[2], 1, d - 1)
        if (s != ref) {
            if (s in map) {
                match(\$0, /^[sieq] +/)
                print substr(\$0, 1, RLENGTH) map[s] substr(\$0, RLENGTH + 1 + length(s)) > out
                n[s]++; next
            }
            if (s in target) die("line " NR " already uses the new name " s ": renaming would merge two species")
        }
    }
    print > out
}
END {
    if (failed) exit 1
    printf "" > out
    if (close(out) != 0) die("cannot write " out)
    for (s in map) print "renamed " s " -> " map[s] ": " n[s] + 0 " line(s)"
}' "\$input"
;;
*) echo "mode must be forward or species: \$mode" >&2; exit 1;;
esac
